-- Purpose: LÖVE 11.5 runtime/headless configuration. API: love.conf. Dependencies: boot args only.
function love.conf(t) t.version='11.5'; t.identity='tindahan'; t.window.title='Tindahan • Neighborhood shop'; t.window.width=1280; t.window.height=720; t.window.highdpi=true; t.window.msaa=4; t.window.resizable=true; t.window.minwidth=960; t.window.minheight=540; t.window.vsync=1; t.modules.physics=false; t.modules.audio=false; for _,value in ipairs(arg or {}) do if value=='--test' or value=='--save-check' or value=='--m3-check' or value=='--check-assets' or value=='--check-navigation' or value=='--check-contrast' then t.window=false; t.modules.graphics=false; t.modules.window=false end end end
